        """Set sunroof to open degree"""
        payload = {
            'component': 'sunroof',
            'value': self.set_open_degree(value, unit),
            'unit': unit
        }

        return await self._make_request('PUT', '/sunroof', payload)

    async def toggle_trunk(self, state: str) -> Dict:
