        payload = {
            'component': 'trunk',
            'action': 'toggle',
            'state': state
        }

        return await self._make_request('POST', f'/trunk/{state}', payload)

    async def set_wiper_speed(self, component: str, value: int, unit: str = 'gear') -> Dict:
        """Set wiper speed"""
        payload = {
            'component': 'wiper',
            'action': 'set_speed',
            'value': value,
            'unit': unit,
            'position': component
        }

        return await self._make_request('PUT', f'/wiper/{component}', payload)

