            'little': {'gear': 2, 'percentage': 25.0},
            'large': {'gear': 3, 'percentage': 50.0}
        }

        increment = adjustments.get(unit, {'gear': 1, 'percentage': 10.0})

        return {
            'value': current_value + increment['gear'],
            'unit': unit if unit != 'little' else 'gear',
            'new_speed': max(1.0, min(current_value + increment['percentage'] / 10, 5.0))
        }
