    def __init__(self):
        self.base_url = "http://vehicle-api.com/v1"

    async def set_sunroof_open(self, value: float, unit: str = 'percentage') -> Dict:
        """Set sunroof to open degree"""
        payload = {
            'component': 'sunroof',
            'value': self.set_open_degree(value, unit),
            'unit': unit
        }

        return await self._make_request('PUT', '/sunroof', payload)

    async def toggle_trunk(self, state: str) -> Dict:
        """Toggle trunk state"""
        payload = {
            'component': 'trunk',
            'action': 'toggle',
            'state': state
        }

        return await self._make_request('POST', f'/trunk/{state}', payload)

    async def set_wiper_speed(self, component: str, value: int, unit: str = 'gear') -> Dict:
        """Set wiper speed"""
        payload = {
            'component': 'wiper',
            'action': 'set_speed',
            'value': value,
            'unit': unit,
            'position': component
        }

        return await self._make_request('PUT', f'/wiper/{component}', payload)

